	@Test
	void optimizationScopeFingerprintsOneFactorIdentityWithoutRenderingDiagnostics() {
		LmdbEvaluationStatistics statistics = statistics();
		CountingValueConstant condition = new CountingValueConstant();
		Filter filter = new Filter(pattern("s", FIRST, "x"), condition);
		PlanningGraphDomains.capture(filter, PlanningGraphDomain.defaultGraph());
		CostContext context = CostContext.of(Set.of(), 1.0d, 1.0d, false);
		int visitsAfterFirstScope;
		try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
			var first = statistics.estimateFactorCost(filter, context).orElseThrow();
			visitsAfterFirstScope = condition.visits();
			assertTrue(visitsAfterFirstScope > 0, "The structural fingerprint must observe the condition");
			assertEquals(0, condition.hashReads(),
					"A cache key must not invoke potentially storage-backed RDF value hashes");
			assertEquals(0, condition.renderings(),
					"A cache key must use algebra identity, not the diagnostic tree rendering");
			var repeated = statistics.estimateFactorCost(filter, context).orElseThrow();
			assertSame(first, repeated);
			assertEquals(visitsAfterFirstScope, condition.visits(),
					"One immutable factor identity must not be structurally traversed again in one planning pass");
			assertEquals(0, condition.hashReads());
			assertEquals(0, condition.renderings());
		}
		try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
			statistics.estimateFactorCost(filter, context).orElseThrow();
			assertTrue(condition.visits() > visitsAfterFirstScope,
					"A new planning pass must not inherit identity-based fingerprints from an earlier query");
			assertEquals(0, condition.hashReads());
			assertEquals(0, condition.renderings());
		}
	}

	@Test
	void optimizationScopeSharesOneLazyBindingUniverseAcrossExpressionIdentities() {
		LmdbFiniteJoinSurfaceEstimator estimator = new LmdbFiniteJoinSurfaceEstimator(null, null, null);
		LmdbEstimatorOptimizationScope firstScope = new LmdbEstimatorOptimizationScope(estimator);
		CountingStatementPattern firstExpression = new CountingStatementPattern("s", FIRST, "x");
		CountingStatementPattern secondExpression = new CountingStatementPattern("x", SECOND, "y");
		BindingUniverse first = firstScope.bindingUniverse(firstExpression);
		BindingUniverse second = firstScope.bindingUniverse(secondExpression);
		assertSame(first, second, "Every estimate in one query must use one stable binding-symbol namespace");
		assertEquals(0, firstExpression.visits());
		assertEquals(0, secondExpression.visits(),
				"Creating an estimate context must not traverse each candidate algebra tree");
		assertEquals(Set.of("s", "x"), first.names(first.maskOf(Set.of("s", "x"))));
		assertEquals(Set.of("x", "y"), second.names(second.maskOf(Set.of("x", "y"))));
		assertNotSame(first, new LmdbEstimatorOptimizationScope(estimator).bindingUniverse(firstExpression),
				"A later query must not inherit the earlier query's binding universe");
	}

	@Test
	void optimizationScopeMaterializesEachFiniteBindingContextOnce() {
		LmdbPrefixEvidenceResolver resolver = new LmdbPrefixEvidenceResolver(null, ignored -> null);
		Map<Map<String, Set<Value>>, Optional<FiniteRelationEstimate>> cache = new HashMap<>();
		Value firstValue = VF.createIRI("urn:finite:first");
		Value secondValue = VF.createIRI("urn:finite:second");
		var cachedFiniteBindings = assertDoesNotThrow(
				() -> LmdbPrefixEvidenceResolver.class.getDeclaredMethod("finiteBindings", Map.class, Map.class),
				"The resolver must expose its query-local finite-context cache boundary");
		FiniteRelationEstimate first = (FiniteRelationEstimate) assertDoesNotThrow(
				() -> cachedFiniteBindings.invoke(resolver, Map.of("x", Set.of(firstValue, secondValue)), cache));
		FiniteRelationEstimate equivalent = (FiniteRelationEstimate) assertDoesNotThrow(
				() -> cachedFiniteBindings.invoke(resolver, Map.of("x", Set.of(secondValue, firstValue)), cache));
		assertSame(first, equivalent,
				"Equivalent finite prefix domains must share one Cartesian relation inside an optimization");
		assertEquals(1, cache.size());
		assertEquals(2.0d, first.rows(), 0.0d);
	}

	@Test
	void optimizationScopeReusesExactCompletedRelationAcrossLastFactorChoices(@TempDir File dataDir) {
		IRI firstPredicate = VF.createIRI("urn:completed-relation:first");
		IRI secondPredicate = VF.createIRI("urn:completed-relation:second");
		IRI thirdPredicate = VF.createIRI("urn:completed-relation:third");
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				for (int row = 0; row < 4; row++) {
					IRI subject = VF.createIRI("urn:completed-relation:subject:" + row);
					IRI middle = VF.createIRI("urn:completed-relation:middle:" + row);
					IRI object = VF.createIRI("urn:completed-relation:object:" + row);
					connection.add(subject, firstPredicate, middle);
					connection.add(middle, secondPredicate, object);
					if (row < 3) {
						connection.add(subject, thirdPredicate, object);
					}
				}
			}
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			LmdbEstimatorRuntime runtime = statistics.estimatorRuntime();
			StatementPattern first = pattern("subject", firstPredicate, "middle");
			StatementPattern second = pattern("middle", secondPredicate, "object");
			StatementPattern third = pattern("subject", thirdPredicate, "object");
			BindingSetAssignment selectedSubjects = values("subject", VF.createIRI("urn:completed-relation:subject:0"),
					VF.createIRI("urn:completed-relation:subject:0"), VF.createIRI("urn:completed-relation:subject:1"),
					VF.createIRI("urn:completed-relation:subject:3"));
			PlanningGraphDomains.capture(selectedSubjects, PlanningGraphDomain.defaultGraph());
			try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
				var secondThenThird = runtime
						.exactDerivedSurface(List.of(selectedSubjects, first, second), third, Map.of())
						.orElseThrow();
				var thirdThenSecond = runtime
						.exactDerivedSurface(List.of(selectedSubjects, third, first), second, Map.of())
						.orElseThrow();
				assertTrue(secondThenThird.exact());
				assertTrue(thirdThenSecond.exact());
				assertEquals(secondThenThird.surfaceRows(), thirdThenSecond.surfaceRows(), 0.0d);
				assertEquals(4.0d, secondThenThird.prefixRows(), 0.0d);
				assertEquals(3.0d, thirdThenSecond.prefixRows(), 0.0d);
				assertEquals(3.0d, secondThenThird.matchedPrefixRows(), 0.0d);
				assertEquals(secondThenThird.matchedPrefixRows(), thirdThenSecond.matchedPrefixRows(), 0.0d);
				assertTrue(secondThenThird.scannedRows() > 0L,
						"The first completed relation must come from one exact snapshot scan");
				assertEquals(0L, thirdThenSecond.scannedRows(),
						"An exact completed-relation hit must not repeat the equivalent snapshot scan");
				assertSame(secondThenThird.relation(), thirdThenSecond.relation(),
						"One completed exact factor multiset must retain one immutable extensional relation");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void completedRelationReuseTreatsUnboundPrefixColumnsAsCompatible(@TempDir File dataDir) {
		IRI firstPredicate = VF.createIRI("urn:completed-unbound:first");
		IRI thirdPredicate = VF.createIRI("urn:completed-unbound:third");
		IRI subject = VF.createIRI("urn:completed-unbound:subject");
		IRI middle = VF.createIRI("urn:completed-unbound:middle");
		IRI object = VF.createIRI("urn:completed-unbound:object");
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.add(subject, firstPredicate, middle);
				connection.add(subject, thirdPredicate, object);
			}
			MapBindingSet selectedSubject = new MapBindingSet();
			selectedSubject.addBinding("subject", subject);
			BindingSetAssignment selectedSubjects = new BindingSetAssignment();
			selectedSubjects.setBindingNames(Set.of("subject", "object"));
			selectedSubjects.setBindingSets(List.of(selectedSubject));
			PlanningGraphDomains.capture(selectedSubjects, PlanningGraphDomain.defaultGraph());
			StatementPattern first = pattern("subject", firstPredicate, "middle");
			StatementPattern third = pattern("subject", thirdPredicate, "object");
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
				var firstThenThird = statistics.estimatorRuntime()
						.exactDerivedSurface(List.of(selectedSubjects, third), first, Map.of())
						.orElseThrow();
				var thirdThenFirst = statistics.estimatorRuntime()
						.exactDerivedSurface(List.of(selectedSubjects, first), third, Map.of())
						.orElseThrow();
				assertEquals(1.0d, firstThenThird.surfaceRows(), 0.0d);
				assertEquals(1.0d, thirdThenFirst.prefixRows(), 0.0d);
				assertEquals(1.0d, thirdThenFirst.matchedPrefixRows(), 0.0d,
						"A final factor may bind an unbound column in an otherwise connected exact prefix row");
				assertEquals(0L, thirdThenFirst.scannedRows());
				assertSame(firstThenThird.relation(), thirdThenFirst.relation());
			}
		} finally {
			repository.shutDown();
		}
	}

