	private static StatisticsEstimate selectedInputEstimate(double rows) {
		BagEstimate bag = BagEstimate.exact(rows, "selected-memo-input")
				.withVariable("s", VariableEstimate.bound(rows, rows))
				.withVariable("x", VariableEstimate.bound(rows, rows));
		return StatisticsEstimate.fromBag(bag, "selected-memo-input");
	}

	private static BindingSetAssignment values(int... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		List<BindingSet> rows = java.util.Arrays.stream(values).mapToObj(value -> {
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("x", VF.createLiteral(value));
			return (BindingSet) bindings;
		}).toList();
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static BindingSetAssignment values(String bindingName, Value... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		List<BindingSet> rows = java.util.Arrays.stream(values).map(value -> {
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding(bindingName, value);
			return (BindingSet) bindings;
		}).toList();
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static final class CountingValueConstant extends ValueConstant {

		private int renderings;

		private int hashReads;

		private int visits;

		private CountingValueConstant() {
			super(VF.createLiteral(true));
		}

		@Override
		public String toString() {
			renderings++;
			return super.toString();
		}

		@Override
		public int hashCode() {
			hashReads++;
			return super.hashCode();
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visits++;
			super.visit(visitor);
		}

		private int renderings() {
			return renderings;
		}

		private int hashReads() {
			return hashReads;
		}

		private int visits() {
			return visits;
		}
	}

	private static final class CountingStatementPattern extends StatementPattern {

		private int visits;

		private CountingStatementPattern(String subject, IRI predicate, String object) {
			super(new Var(subject), new Var("predicate", predicate), new Var(object));
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visits++;
			super.visit(visitor);
		}

		private int visits() {
			return visits;
		}
	}

	private static final class CountingValue implements Value {

		private static final long serialVersionUID = 1L;

		private final String lexicalValue;

		private int stringValueReads;

		private CountingValue(String lexicalValue) {
			this.lexicalValue = lexicalValue;
		}

		@Override
		public String stringValue() {
			stringValueReads++;
			return lexicalValue;
		}

		private int stringValueReads() {
			return stringValueReads;
		}
	}

	private static final class HashUnsafeValue implements Value {

		private static final long serialVersionUID = 1L;

		private final String lexicalValue;

		private HashUnsafeValue(String lexicalValue) {
			this.lexicalValue = lexicalValue;
		}

		@Override
		public String stringValue() {
			return lexicalValue;
		}

		@Override
		public boolean equals(Object other) {
			return other instanceof HashUnsafeValue that && lexicalValue.equals(that.lexicalValue);
		}

		@Override
		public int hashCode() {
			throw new AssertionError("query-local fingerprints must not invoke RDF value hashCode");
		}
	}

	@Test
	void samplesPatternLocalFilterAcrossAnOrderIndependentOfTheFilteredVariable() throws Exception {
		File dataDir = Files.createTempDirectory("lmdb-eval-stats-ordered-filter").toFile();
		LmdbStoreConfig config = new LmdbStoreConfig().setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(true)
				.setOptimizerSamplingMaxMillis(5_000L)
				.setOptimizerSamplingMaxRows(16);
		config.setExperimentalQueryOptimizations(true);
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, config));
		try {
			loadInterleavedDateData(repository);
			LmdbStore sail = (LmdbStore) repository.getSail();
			LmdbSailStore backingStore = sail.getBackingStore();
			rebuildSketchesAndAwaitLmdbOptimizer(sail, backingStore);
			EvaluationStatistics statistics = backingStore.getEvaluationStatistics();
			Filter filter = firstFilter("""
					SELECT * WHERE {
						?s <urn:test:recordedOn> ?date .
						FILTER(?date IN (
							"2024-01-01"^^<http://www.w3.org/2001/XMLSchema#date>,
							"2024-02-01"^^<http://www.w3.org/2001/XMLSchema#date>
						))
					}
					""");
			EvaluationStatistics.FilterPassEstimate estimate = statistics.estimateFilterPass(filter);
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.SAMPLED, estimate.getSource());
			assertTrue(estimate.getPassRatio() > 0.0d && estimate.getPassRatio() < 0.75d,
					() -> "A bounded sample must not mistake the first object-ordered run for the population: "
							+ estimate);
			assertEquals(16L, estimate.getEvidenceCount());
		} finally {
			repository.shutDown();
			LmdbTestUtil.deleteDir(dataDir);
		}
	}

	private static List<JoinOrderPlanner.PlanStep> planSteps(List<TupleExpr> args, double outputRows,
			double stepWorkRows) {
		List<JoinOrderPlanner.PlanStep> steps = new ArrayList<>();
		for (int i = 0; i < args.size(); i++) {
			steps.add(new JoinOrderPlanner.PlanStep(Set.of(), outputRows, outputRows, stepWorkRows,
					Map.of(TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE, "directLookup"),
					Map.of(TelemetryMetricNames.PLANNED_WORK_ROWS, stepWorkRows), List.of()));
		}
		return steps;
	}

